import argparse,json,sys,subprocess,shutil
from pathlib import Path
sys.path.insert(0,'scripts');import inspection
p=Path('vendor/quinn/src/event_queue.rs');out=Path('artifacts/webtransport');saved=p.read_bytes()
try:
 s=saved.decode();s=s.replace('pub(crate) struct BufferPool<T> {','pub(crate) struct BufferPool<T> {\n    takes: std::sync::atomic::AtomicU64,\n    hits: std::sync::atomic::AtomicU64,',1)
 needle='            spare: Mutex::new(Vec::with_capacity(slots)),';assert needle in s;s=s.replace(needle,needle+'\n            takes: std::sync::atomic::AtomicU64::new(0),\n            hits: std::sync::atomic::AtomicU64::new(0),',1)
 a=s.index('    fn take(&self) -> VecDeque<T> {');b=s.index('\n    fn recycle',a)
 s=s[:a]+'''    fn take(&self) -> VecDeque<T> {
        let buffer = self.spare.lock().unwrap_or_else(|e| e.into_inner()).pop();
        self.takes.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        if buffer.is_some() { self.hits.fetch_add(1, std::sync::atomic::Ordering::Relaxed); }
        buffer.unwrap_or_default()
    }
'''+s[b:]
 marker='#[derive(Debug)]\nstruct State<T>';assert marker in s;s=s.replace(marker,'''impl<T> Drop for BufferPool<T> {
 fn drop(&mut self) { eprintln!("EVENT_POOL_CENSUS takes={} hits={}",self.takes.load(std::sync::atomic::Ordering::Relaxed),self.hits.load(std::sync::atomic::Ordering::Relaxed)); }
}

'''+marker)
 s=s.replace('hits: std::sync::atomic::AtomicU64,', 'hits: std::sync::atomic::AtomicU64,\n    full: std::sync::atomic::AtomicU64,',1)
 s=s.replace('hits: std::sync::atomic::AtomicU64::new(0),','hits: std::sync::atomic::AtomicU64::new(0),\n            full: std::sync::atomic::AtomicU64::new(0),',1)
 s=s.replace('spare.push(buffer);','spare.push(buffer);\n        } else { self.full.fetch_add(1,std::sync::atomic::Ordering::Relaxed);',1)
 s=s.replace('takes={} hits={}', 'takes={} hits={} full={} slots={}')
 s=s.replace('self.hits.load(std::sync::atomic::Ordering::Relaxed));','self.hits.load(std::sync::atomic::Ordering::Relaxed),self.full.load(std::sync::atomic::Ordering::Relaxed),self.slots);')
 p.write_text(s);(out/'event-batch-full-census-source.rs').write_text(s)
 with (out/'event-batch-full-census-build.log').open('x') as f:subprocess.run(['cargo','build','--release'],stdout=f,stderr=f,check=True)
 shutil.copy2('target/release/war-relay',out/'binaries/event-batch-full-census-relay')
finally:
 p.write_bytes(saved);shutil.copy2(out/'binaries/event-batch-relay','target/release/war-relay')
for case in ['private','mixed']:
 a=json.loads((out/f'owner-poll-{case}-owner-poll-1.json').read_text())['args'];a.update(server=str((out/'binaries/event-batch-full-census-relay').resolve()),output=str((out/f'event-batch-full-census-{case}.json').resolve()))
 for k in ['server','client','client_source_root','tls_front','tls_cert','tls_key','tls_ca','heap_profile','heap_library','output','fanout_latency_output']:
  if a.get(k) is not None:a[k]=Path(a[k])
 r=inspection.run(argparse.Namespace(**a));r['profile_diagnostic']=True;r['scope']='Diagnostic cache counters only; exclude timing and RSS from ordinary comparisons.';a['output'].write_text(json.dumps(r,indent=2)+'\n');assert r['passed'];print('CENSUS',case,[x for x in r['server_log'].splitlines() if 'EVENT_POOL_CENSUS' in x],flush=True)

